import timeescape.core.*;import timeescape.scene.*;import timeescape.ui.*;import timeescape.model.*;import java.awt.*;import java.awt.image.*;import javax.swing.*;import javax.imageio.*;import java.nio.file.*;
public class VerifyProgressHints {
 static int checks;static void check(boolean b,String s){if(!b)throw new AssertionError(s);checks++;}static void hint(GameState s,String id,InteractionHint h){check(InteractionHint.of(s,id)==h,id+" expected "+h);}
 static java.lang.reflect.Field f(String n)throws Exception{var f=GameScenePanel.class.getDeclaredField(n);f.setAccessible(true);return f;}
 static BufferedImage draw(GameScenePanel p,double phase)throws Exception{f("particlePhase").setDouble(p,phase);BufferedImage im=new BufferedImage(1920,1080,BufferedImage.TYPE_INT_RGB);var g=im.createGraphics();p.printAll(g);g.dispose();return im;}
 static boolean changed(BufferedImage a,BufferedImage b,String id){Hotspot h=HotspotCatalog.of(Era.PRESENT).stream().filter(x->x.id().equals(id)).findFirst().orElseThrow();Rectangle r=h.bounds();for(int y=r.y;y<r.y+r.height;y++)for(int x=r.x;x<r.x+r.width;x++)if(a.getRGB(x,y)!=b.getRGB(x,y))return true;return false;}
 public static void main(String[] args)throws Exception{
 GameState s=new GameState();hint(s,"POWER",InteractionHint.READY);for(String id:new String[]{"PRESENT_PC","MEMO","WORKBENCH","USB","CASE","CELL","MODULE"})hint(s,id,InteractionHint.LATER);
 s.complete("PZ004");hint(s,"POWER",InteractionHint.NONE);hint(s,"MEMO",InteractionHint.READY);hint(s,"WORKBENCH",InteractionHint.READY);hint(s,"PRESENT_PC",InteractionHint.LATER);hint(s,"USB",InteractionHint.READY);
 SwingUtilities.invokeAndWait(()->{try{GameFonts.installDefaults();GameScenePanel p=new GameScenePanel(x->{});p.setSize(1920,1080);p.setEra(Era.PRESENT);p.restorePowered(true);p.setProgressHints(s);f("revealContrast").setFloat(p,1);
 BufferedImage a=draw(p,0),b=draw(p,.6);check(!changed(a,b,"POWER"),"completed no particles");check(!changed(a,b,"PRESENT_PC"),"later no particles");check(changed(a,b,"MEMO"),"ready particles active");var mask=(BufferedImage)f("contrastMask").get(p);check((mask.getRGB(805/2,365/2)>>>24)==128,"completed darkened with background");check((mask.getRGB(940/2,540/2)>>>24)==0,"later retains object light");check((mask.getRGB(325/2,390/2)>>>24)==0,"ready retains object light");
 ImageIO.write(a,"png",Path.of("outputs/v62-validation/shift-progress.png").toFile());s.complete("PZ006");p.setProgressHints(s);check(f("contrastMask").get(p)==null,"progress invalidates mask");draw(p,0);check(f("contrastMask").get(p)!=mask,"rebuilt mask after progress");}catch(Exception e){throw new RuntimeException(e);}});
 hint(s,"MEMO",InteractionHint.NONE);hint(s,"PRESENT_PC",InteractionHint.READY);s.complete("PZ001");hint(s,"PRESENT_PC",InteractionHint.LATER);s.collect("USB");hint(s,"USB",InteractionHint.NONE);hint(s,"PRESENT_PC",InteractionHint.READY);s.complete("PZ007");hint(s,"PRESENT_PC",InteractionHint.NONE);
 s.complete("PZ008");hint(s,"WORKBENCH",InteractionHint.LATER);for(String id:new String[]{"CASE","CELL","MODULE"}){hint(s,id,InteractionHint.READY);s.collect(id);hint(s,id,InteractionHint.NONE);}hint(s,"WORKBENCH",InteractionHint.READY);s.complete("PZ010");for(String id:new String[]{"CASE","CELL","MODULE"})hint(s,id,InteractionHint.NONE);hint(s,"WORKBENCH",InteractionHint.READY);s.complete("PZ011");hint(s,"WORKBENCH",InteractionHint.NONE);
 GameState restored=GameState.restore(s.catalog(),s.snapshot());for(Hotspot h:HotspotCatalog.of(Era.PRESENT))check(InteractionHint.of(s,h.id())==InteractionHint.of(restored,h.id()),"restored hint "+h.id());
 s.moveToPast();hint(s,"PAST_SPARE",InteractionHint.READY);s.complete("PZ002");hint(s,"PAST_SPARE",InteractionHint.NONE);s.repairWatch();s.moveToFuture();hint(s,"FUTURE_CORE",InteractionHint.READY);s.complete("PZ003");hint(s,"FUTURE_CORE",InteractionHint.NONE);
 System.out.println("PASS "+checks+" progress hint, mask, particle and restore checks; no game window");
 }
}
